@Singleton
public class LeadmanPanel extends PluginPanel
{
	private static final int CARD_GAP = 2;

	private final UnlockService unlockService;
	private final RuleRepository rules;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final SkillIconManager skillIcons;
	private final ItemCatalogDialog catalog;

	private final IconTextField search = LeadmanUi.createSearchField();
	private final JPanel itemsList = new JPanel();
	private final JLabel summary = new JLabel();
	private final JButton catalogButton = new JButton("\u2699");

	private List<Row> itemRows = new ArrayList<>();
	private final Map<String, Integer> itemIdCache = new HashMap<>();

	@Inject
	public LeadmanPanel(
		UnlockService unlockService,
		RuleRepository rules,
		ClientThread clientThread,
		ItemManager itemManager,
		SkillIconManager skillIcons,
		ItemCatalogDialog catalog)
	{
		super(false);
		this.unlockService = unlockService;
		this.rules = rules;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.skillIcons = skillIcons;
		this.catalog = catalog;
	}

	public void init()
	{
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		summary.setFont(FontManager.getRunescapeSmallFont());
		summary.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		summary.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		search.setToolTipText("Filter your unlocks");
		search.getDocument().addDocumentListener(filterListener());

		catalogButton.setToolTipText("Browse and edit all items");
		catalogButton.setPreferredSize(new Dimension(32, 30));
		LeadmanUi.styleSecondaryButton(catalogButton);
		catalogButton.addActionListener(e -> catalog.open(this));

		JPanel summaryRow = new JPanel(new BorderLayout(6, 0));
		LeadmanUi.darkPanel(summaryRow);
		summaryRow.add(summary, BorderLayout.CENTER);
		summaryRow.add(catalogButton, BorderLayout.EAST);

		JPanel head = new JPanel(new BorderLayout());
		LeadmanUi.darkPanel(head);
		head.add(summaryRow, BorderLayout.NORTH);
		head.add(search, BorderLayout.CENTER);

		itemsList.setLayout(new BoxLayout(itemsList, BoxLayout.Y_AXIS));
		LeadmanUi.darkPanel(itemsList);

		add(head, BorderLayout.NORTH);
		add(scroll(itemsList), BorderLayout.CENTER);

		LeadmanUi.styleSearchFieldInternals(search);
		refresh();
	}

	private DocumentListener filterListener()
	{
		return new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				renderItems();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				renderItems();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				renderItems();
			}
		};
	}

	private JScrollPane scroll(JPanel content)
	{
		JPanel wrapper = new JPanel(new BorderLayout());
		LeadmanUi.darkPanel(wrapper);
		wrapper.add(content, BorderLayout.NORTH);

		JScrollPane pane = new JScrollPane(wrapper);
		pane.setBorder(BorderFactory.createEmptyBorder());
		pane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		pane.setBackground(ColorScheme.DARK_GRAY_COLOR);
		pane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		pane.getVerticalScrollBar().setUnitIncrement(16);
		return pane;
	}

	public void refresh()
	{
		clientThread.invoke(() -> {
			if (!unlockService.isLoaded())
			{
				SwingUtilities.invokeLater(this::renderItems);
				return;
			}

			List<Row> rows = new ArrayList<>();
			for (String key : unlockService.getPanelUnlockKeys())
			{
				ItemRule rule = rules.forName(key);
				String display = rule != null ? rule.getDisplay() : key;
				CustomRule custom = unlockService.getCustomRule(key);
				List<LeadmanUi.ActionLine> actions = RuleDisplayUtil.actionLines(
					unlockService, key, rule, custom);
				rows.add(new Row(key, display, actions));
			}

			SwingUtilities.invokeLater(() -> {
				itemRows = rows;
				updateSummary();
				renderItems();
			});
		});
	}

	private void updateSummary()
	{
		if (!unlockService.isLoaded())
		{
			summary.setText("Log in to track your unlocks.");
			return;
		}

		summary.setText("Unlocks (" + itemRows.size() + ")");
	}

	private void renderItems()
	{
		updateSummary();
		String filter = search.getText().trim().toLowerCase();
		itemsList.removeAll();

		if (!unlockService.isLoaded())
		{
			itemsList.add(LeadmanUi.hintLabel("Log in to see your unlocks here."));
		}
		else if (itemRows.isEmpty())
		{
			itemsList.add(LeadmanUi.hintLabel("Obtain items or level up to populate this list."));
		}
		else
		{
			int shown = 0;
			for (Row row : itemRows)
			{
				if (!filter.isEmpty() && !row.displayName.toLowerCase().contains(filter))
				{
					continue;
				}
				shown++;
				itemsList.add(buildItemRow(row));
				itemsList.add(Box.createVerticalStrut(CARD_GAP));
			}

			if (shown == 0)
			{
				itemsList.add(LeadmanUi.hintLabel("Nothing matches your search."));
			}
		}

		itemsList.revalidate();
		itemsList.repaint();
	}

	private JPanel buildItemRow(Row row)
	{
		JPanel card = LeadmanUi.itemCard(
			null,
			row.displayName,
			true,
			LeadmanUi.actionLines(skillIcons, row.actions),
			null);

		attachItemIcon(card, row.ruleKey, row.displayName);
		return card;
	}

	private void attachItemIcon(JPanel card, String cacheKey, String displayName)
	{
		JLabel iconLabel = findIconLabel(card);
		if (iconLabel == null)
		{
			return;
		}

		Integer cached = itemIdCache.get(cacheKey);
		if (cached != null)
		{
			if (cached > 0)
			{
				itemManager.getImage(cached).addTo(iconLabel);
			}
			return;
		}

		clientThread.invoke(() -> {
			int itemId = -1;
			for (var price : itemManager.search(displayName))
			{
				if (displayName.equalsIgnoreCase(itemManager.getItemComposition(price.getId()).getName()))
				{
					itemId = price.getId();
					break;
				}
			}
			if (itemId <= 0 && !itemManager.search(displayName).isEmpty())
			{
				itemId = itemManager.search(displayName).get(0).getId();
			}
			itemIdCache.put(cacheKey, itemId);
			if (itemId > 0)
			{
				itemManager.getImage(itemId).addTo(iconLabel);
			}
		});
	}

	private static JLabel findIconLabel(JPanel card)
	{
		for (Component child : card.getComponents())
		{
			if (child instanceof JPanel)
			{
				for (Component westChild : ((JPanel) child).getComponents())
				{
					if (westChild instanceof JLabel)
					{
						return (JLabel) westChild;
					}
				}
			}
		}
		return null;
	}

	private static final class Row
	{
		private final String ruleKey;
		private final String displayName;
		private final List<LeadmanUi.ActionLine> actions;

		private Row(String ruleKey, String displayName, List<LeadmanUi.ActionLine> actions)
		{
			this.ruleKey = ruleKey;
			this.displayName = displayName;
			this.actions = actions;
		}
	}
}

package com.leadman.ui;

import com.leadman.rules.ConsumeClass;
import com.leadman.rules.ItemRule;
import com.leadman.rules.PathType;
import com.leadman.rules.Requirement;
import com.leadman.rules.UnlockPath;
import com.leadman.unlock.CustomRule;
import com.leadman.unlock.UnlockService;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Skill;

/** Shared helpers for turning rules into panel display values. */
public final class RuleDisplayUtil
{
	private RuleDisplayUtil()
	{
	}

	static List<LeadmanUi.ActionLine> actionLines(
		UnlockService unlockService,
		String key,
		ItemRule rule,
		CustomRule custom)
	{
		List<LeadmanUi.ActionLine> lines = new ArrayList<>();
		if (rule == null && custom == null)
		{
			return lines;
		}

		addLine(lines, "Can trade:", unlockService.meetsTradeRequirements(key),
			fromRequirements(unlockService.displayTradeRequirements(key)), rule, true);

		addLine(lines, "Can shop:", unlockService.meetsShopRequirements(key),
			fromRequirements(unlockService.displayShopRequirements(key)), rule, true);

		addLine(lines, "Can use:", unlockService.meetsUseRequirements(key),
			useMenuLevels(custom, rule, key, unlockService), rule, false);

		addLine(lines, "Can eat:", unlockService.meetsEatRequirements(key),
			fromRequirements(unlockService.displayEatRequirements(key)), rule, false);

		addLine(lines, "Can drink:", unlockService.meetsDrinkRequirements(key),
			fromRequirements(unlockService.displayDrinkRequirements(key)), rule, false);

		addLine(lines, "Can wield:", unlockService.meetsWieldRequirements(key),
			fromRequirements(unlockService.displayWieldRequirements(key)), rule, false);

		addLine(lines, "Can teleport:", unlockService.meetsActivateRequirements(key),
			fromRequirements(unlockService.displayActivateRequirements(key)), rule, false);

		addLine(lines, "Can bury:", unlockService.meetsBuryRequirements(key),
			fromRequirements(unlockService.displayBuryRequirements(key)), rule, false);

		return lines;
	}

	public static boolean hasLockedActions(
		UnlockService unlockService,
		String key,
		ItemRule rule,
		CustomRule custom)
	{
		return actionLines(unlockService, key, rule, custom).stream()
			.anyMatch(line -> !line.unlocked);
	}

	/** Comma-separated list of locked action names, or null if everything is open. */
	public static String lockedActionsSummary(
		UnlockService unlockService,
		String key,
		ItemRule rule,
		CustomRule custom)
	{
		List<String> locked = new ArrayList<>();
		for (LeadmanUi.ActionLine line : actionLines(unlockService, key, rule, custom))
		{
			if (!line.unlocked)
			{
				locked.add(line.label.replace(":", "").trim());
			}
		}
		return locked.isEmpty() ? null : String.join(", ", locked);
	}

	private static void addLine(
		List<LeadmanUi.ActionLine> lines,
		String label,
		boolean unlocked,
		List<LeadmanUi.SkillLevel> levels,
		ItemRule rule,
		boolean showObtainFallback)
	{
		if (levels.isEmpty())
		{
			if (showObtainFallback && rule != null && rule.getPaths().isEmpty())
			{
				lines.add(new LeadmanUi.ActionLine(label, unlocked, levels));
			}
			return;
		}
		lines.add(new LeadmanUi.ActionLine(label, unlocked, levels));
	}

	private static List<LeadmanUi.SkillLevel> useMenuLevels(
		CustomRule custom,
		ItemRule rule,
		String key,
		UnlockService unlockService)
	{
		List<LeadmanUi.SkillLevel> scoped = fromRequirements(unlockService.displayUseRequirements(key));
		if (!scoped.isEmpty())
		{
			return scoped;
		}
		if (rule == null)
		{
			return scoped;
		}
		ConsumeClass consume = rule.getConsume();
		if (consume == ConsumeClass.FOOD
			|| consume == ConsumeClass.POTION
			|| consume == ConsumeClass.JEWELLERY)
		{
			return scoped;
		}
		return scoped;
	}

	static List<LeadmanUi.SkillLevel> fromRequirements(List<Requirement> reqs)
	{
		List<LeadmanUi.SkillLevel> levels = new ArrayList<>();
		if (reqs == null)
		{
			return levels;
		}
		for (Requirement req : reqs)
		{
			Skill skill = req.getSkill();
			if (skill != null)
			{
				levels.add(new LeadmanUi.SkillLevel(skill, req.getLevel()));
			}
		}
		return levels;
	}

	static List<LeadmanUi.SkillLevel> tradeReqs(ItemRule rule)
	{
		return fromRequirements(collectFromRule(rule, true, false, false, false, false));
	}

	static List<LeadmanUi.SkillLevel> shopReqs(ItemRule rule)
	{
		return tradeReqs(rule);
	}

	static List<LeadmanUi.SkillLevel> useReqs(ItemRule rule)
	{
		return fromRequirements(collectFromRule(rule, false, true, false, false, false));
	}

	static List<LeadmanUi.SkillLevel> eatReqs(ItemRule rule)
	{
		if (rule == null || rule.getConsume() != ConsumeClass.FOOD)
		{
			return new ArrayList<>();
		}
		return wearDisplayLevels(rule);
	}

	static List<LeadmanUi.SkillLevel> drinkReqs(ItemRule rule)
	{
		if (rule == null || rule.getConsume() != ConsumeClass.POTION)
		{
			return new ArrayList<>();
		}
		return wearDisplayLevels(rule);
	}

	static List<LeadmanUi.SkillLevel> wieldReqs(ItemRule rule)
	{
		return fromRequirements(collectFromRule(rule, false, false, true, false, false));
	}

	static List<LeadmanUi.SkillLevel> activateReqs(ItemRule rule)
	{
		return fromRequirements(collectFromRule(rule, false, false, false, true, false));
	}

	static List<LeadmanUi.SkillLevel> buryReqs(ItemRule rule)
	{
		return fromRequirements(collectFromRule(rule, false, false, false, false, true));
	}

	static LeadmanUi.SkillLevel firstSkillLevel(List<LeadmanUi.SkillLevel> levels)
	{
		if (levels.isEmpty())
		{
			return new LeadmanUi.SkillLevel(Skill.ATTACK, 1);
		}
		return levels.get(0);
	}

	private static List<LeadmanUi.SkillLevel> wearDisplayLevels(ItemRule rule)
	{
		List<LeadmanUi.SkillLevel> levels = new ArrayList<>();
		for (UnlockPath path : rule.getPaths())
		{
			if (path.getType() != PathType.SKILL)
			{
				continue;
			}
			for (Requirement req : path.getReqs())
			{
				if (req.isTradeOnly())
				{
					Skill skill = req.getSkill();
					if (skill != null)
					{
						levels.add(new LeadmanUi.SkillLevel(skill, req.getLevel()));
					}
				}
			}
			if (!levels.isEmpty())
			{
				return levels;
			}
		}
		return levels;
	}

	private static List<Requirement> collectFromRule(
		ItemRule rule,
		boolean trade,
		boolean use,
		boolean wield,
		boolean activate,
		boolean bury)
	{
		List<Requirement> collected = new ArrayList<>();
		if (rule == null)
		{
			return collected;
		}
		for (UnlockPath path : rule.getPaths())
		{
			if (path.getType() != PathType.SKILL)
			{
				continue;
			}
			for (Requirement req : path.getReqs())
			{
				if (trade && (req.isTradeOnly() || req.isActivateOnly()))
				{
					collected.add(req);
				}
				else if (use && req.isUseOnly())
				{
					collected.add(req);
				}
				else if (wield && req.isWieldOnly())
				{
					collected.add(req);
				}
				else if (activate && req.isActivateOnly())
				{
					collected.add(req);
				}
				else if (bury && req.isBuryOnly())
				{
					collected.add(req);
				}
			}
			if (!collected.isEmpty())
			{
				return collected;
			}
		}
		return collected;
	}
}

