 * an elemental staff supplies runes you never owned, and gating the item alone would
 * let a 30k staff launder a third of the rule. See docs/DESIGN.md section 6.1.
 */
public class SpellRule
{
	private String name;
	private List<String> runes;
	/** Teleports, alchemy, enchanting and other non-combat casts. */
	private boolean utility;

	public SpellRule()
	{
	}

	public String getName()
	{
		return name;
	}

	public List<String> getRunes()
	{
		return runes == null ? Collections.emptyList() : runes;
	}

	public boolean isUtility()
	{
		return utility;
	}
}

package com.leadman.rules;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.client.game.ItemStats;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

/**
 * Grand Exchange tradeables bundled from the wiki prices API. Unmapped items with no
 * fabrication rule fall back to equip detection: equippable items trade freely; everything
 * else unlocks on first obtain.
 */
@Slf4j
@Singleton
public class TradeableIndex
{
	private static final Type KEY_LIST = new TypeToken<List<String>>()
	{
	}.getType();
	private static final Type ID_MAP = new TypeToken<Map<String, Integer>>()
	{
	}.getType();

	private final ItemManager itemManager;
	private Set<String> geTradeableKeys = Collections.emptySet();
	private Map<String, Integer> geItemIds = Collections.emptyMap();
	private Map<Integer, String> geIdToKey = Collections.emptyMap();

	@Inject
	TradeableIndex(ItemManager itemManager, Gson gson)
	{
		this.itemManager = itemManager;
		loadBundled(gson);
		loadItemIds(gson);
	}

	private void loadBundled(Gson gson)
	{
		try (InputStream in = TradeableIndex.class.getResourceAsStream("/com/leadman/ge-tradeables.json"))
		{
			if (in == null)
			{
				log.warn("Leadman: ge-tradeables.json missing; unmapped GE items stay blocked by default");
				return;
			}
			List<String> loaded = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), KEY_LIST);
			if (loaded != null)
			{
				geTradeableKeys = new HashSet<>(loaded);
				log.info("Leadman: loaded {} GE tradeable names", geTradeableKeys.size());
			}
		}
		catch (Exception e)
		{
			log.warn("Leadman: could not read ge-tradeables.json", e);
		}
	}

	private void loadItemIds(Gson gson)
	{
		try (InputStream in = TradeableIndex.class.getResourceAsStream("/com/leadman/ge-item-ids.json"))
		{
			if (in == null)
			{
				log.warn("Leadman: ge-item-ids.json missing; equip detection falls back to obtain-only");
				return;
			}
			Map<String, Integer> loaded = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), ID_MAP);
			if (loaded != null)
			{
				geItemIds = new HashMap<>(loaded);
				Map<Integer, String> reverse = new HashMap<>();
				for (Map.Entry<String, Integer> entry : geItemIds.entrySet())
				{
					reverse.putIfAbsent(entry.getValue(), entry.getKey());
				}
				geIdToKey = Collections.unmodifiableMap(reverse);
			}
		}
		catch (Exception e)
		{
			log.warn("Leadman: could not read ge-item-ids.json", e);
		}
	}

	public boolean isGeTradeableKey(String key)
	{
		if (key == null || key.isEmpty())
		{
			return false;
		}
		return geTradeableKeys.contains(key);
	}

	public boolean isGeTradeableId(int itemId)
	{
		if (itemId <= 0)
		{
			return false;
		}
		int canonical = itemManager.canonicalize(itemId);
		if (geIdToKey.containsKey(canonical))
		{
			return true;
		}
		ItemComposition comp = itemManager.getItemComposition(canonical);
		return comp != null && comp.isGeTradeable();
	}

	/**
	 * Canonical rules/GE key for a tradeable item id, from the bundled wiki mapping.
	 * Prefer this over normalising the client display name — in-game names can omit
	 * suffixes such as {@code (tablet)} that the ruleset uses.
	 */
	public String geKeyForItemId(int itemId)
	{
		if (itemId <= 0)
		{
			return null;
		}
		return geIdToKey.get(itemManager.canonicalize(itemId));
	}

	/**
	 * Whether an unmapped GE item may trade or shop without a fabrication rule. Equippable
	 * gear is always open; supplies and miscellany need one obtain first.
	 */
	public boolean isEquippableKey(String key)
	{
		if (key == null || key.isEmpty())
		{
			return false;
		}
		Integer id = geItemIds.get(key);
		if (id == null)
		{
			return false;
		}
		ItemStats stats = itemManager.getItemStats(id);
		return stats != null && stats.isEquipable();
	}
}

package com.leadman.rules;

/** What kind of thing satisfies an {@link UnlockPath}. */
public enum PathType
{
	/** Satisfied by skill levels. */
	SKILL,
	/** Satisfied by a completed quest, diary or activity flag. */
	ACTIVITY
}

package com.leadman.rules;

import java.util.regex.Pattern;

/**
 * Collapses the many in-game spellings of one conceptual item down to a single
 * lookup key, so that "Amulet of glory(6)", "Amulet of glory (t4)" and
 * "Amulet of glory" all resolve to the same rule.
 *
 * <p>Noted and placeholder ids are handled upstream by
 * {@code ItemManager#canonicalize}; this class only deals with the name text.
 */
public final class ItemNames
{
	/** Dose or charge counts: (1) (4) (6) (8) (10). */
	private static final Pattern CHARGES = Pattern.compile("\\(\\d+\\)$");

	/** Cosmetic, imbue, poison and trim suffixes. */
	private static final Pattern SUFFIXES = Pattern.compile(
		"\\((?:t\\d*|g|or|i|l|u|p\\+{0,2}|nz|cr|m|e|x|s|broken|inactive|free|deadman|last man standing)\\)$");

	/** Barrows-style degradation: "Ahrim's robetop 75". */
	private static final Pattern DEGRADE = Pattern.compile("\\s(?:0|25|50|75|100)$");

	private ItemNames()
	{
	}

	/**
	 * @param raw an item's in-game name
	 * @return lowercase canonical key, or an empty string for a null/blank name
	 */
	public static String normalise(String raw)
	{
		if (raw == null)
		{
			return "";
		}

		String s = raw.trim().toLowerCase();
		if (s.isEmpty() || "null".equals(s))
		{
			return "";
		}

		// Strip repeatedly: "Amulet of glory (t4)" can carry more than one marker.
		boolean changed = true;
		while (changed)
		{
			changed = false;

			String next = CHARGES.matcher(s).replaceFirst("");
			if (!next.equals(s))
			{
				s = next.trim();
				changed = true;
			}

			next = SUFFIXES.matcher(s).replaceFirst("");
			if (!next.equals(s))
			{
				s = next.trim();
				changed = true;
			}

			// Only apply the degrade rule to barrows-shaped names, so that a genuine
			// item ending in a number is never truncated.
			if (s.contains("'s "))
			{
				next = DEGRADE.matcher(s).replaceFirst("");
				if (!next.equals(s))
				{
					s = next.trim();
					changed = true;
				}
			}
		}

		return s;
	}

	/** Title-cases a normalised key for display when no display name was supplied. */
	public static String display(String normalised)
	{
		if (normalised == null || normalised.isEmpty())
		{
			return "";
		}
		return Character.toUpperCase(normalised.charAt(0)) + normalised.substring(1);
	}
}

package com.leadman.rules;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads the generated ruleset from resources and answers "what gates this item".
 *
 * <p>The bundled file is produced by {@code tools/generate-rules.mjs} and should not be
 * hand-edited -- put corrections in {@code overrides.json}, which is layered on top and
 * is never regenerated.
 */
@Slf4j
@Singleton
public class RuleRepository
{
	private static final String RULES = "/com/leadman/leadman-rules.json";
	private static final String OVERRIDES = "/com/leadman/overrides.json";

	private final Gson gson;

	private Map<String, ItemRule> byName = Collections.emptyMap();
	private Map<String, SpellRule> spellsByName = Collections.emptyMap();

	@Inject
	public RuleRepository(Gson gson)
	{
		this.gson = gson;
	}

	public void load()
	{
		RuleFile base = read(RULES);
		RuleFile overrides = read(OVERRIDES);

		Map<String, ItemRule> items = new HashMap<>();
		Map<String, SpellRule> spells = new HashMap<>();

		index(base, items, spells);
		// Overrides win outright: an overridden item replaces the generated rule
		// rather than merging with it, so a correction is always predictable.
		index(overrides, items, spells);

		byName = Collections.unmodifiableMap(items);
		spellsByName = Collections.unmodifiableMap(spells);

		log.info("Leadman: loaded {} item rules and {} spell rules", byName.size(), spellsByName.size());
	}

	private void index(RuleFile file, Map<String, ItemRule> items, Map<String, SpellRule> spells)
	{
		if (file == null)
		{
			return;
		}

		if (file.items != null)
		{
			for (ItemRule rule : file.items)
			{
				if (rule == null || rule.getName() == null)
				{
					continue;
				}
				String key = ItemNames.normalise(rule.getName());
				if (key.isEmpty())
				{
					continue;
				}
				rule.setName(key);
				items.put(key, rule);
			}
		}

		if (file.spells != null)
		{
			for (SpellRule spell : file.spells)
			{
				if (spell == null || spell.getName() == null)
				{
					continue;
				}
				spells.put(spell.getName().toLowerCase().trim(), spell);
			}
		}
	}

	private RuleFile read(String resource)
	{
		try (InputStream in = RuleRepository.class.getResourceAsStream(resource))
		{
			if (in == null)
			{
				log.debug("Leadman: no resource at {}", resource);
				return null;
			}
			return gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), RuleFile.class);
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.warn("Leadman: could not read {}", resource, e);
			return null;
		}
	}

	/**
	 * @param itemName raw in-game item name
	 * @return the rule, or null when the item has no mapped gate (treated as free)
	 */
	public ItemRule forName(String itemName)
	{
		if (itemName == null)
		{
			return null;
		}

		String key = ItemNames.normalise(itemName);
		ItemRule rule = byName.get(key);
		if (rule != null)
		{
			return rule;
		}

		// Client names often drop the "(tablet)" suffix used in the ruleset / GE catalog.
		if (!key.endsWith("(tablet)"))
		{
			return byName.get(key + " (tablet)");
		}

		return null;
	}

	public SpellRule forSpell(String spellName)
	{
		if (spellName == null)
		{
			return null;
		}
		return spellsByName.get(spellName.toLowerCase().trim());
	}

	public Map<String, ItemRule> all()
	{
		return byName;
	}

	public int size()
	{
		return byName.size();
	}

	/** Wire format of the bundled JSON files. */
	private static final class RuleFile
	{
		private int version;
		private String generated;
		private List<ItemRule> items;
		private List<SpellRule> spells;
	}
}

package com.leadman.rules;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;

/**
 * One legitimate way to produce an item. All requirements in a path must be met;
 * an item is fabricable when <em>any</em> of its paths is satisfied.
 */
public class UnlockPath
{
	private PathType type;
	private List<Requirement> reqs;
	private String source;
	/** For ACTIVITY paths: the flag key that must be present in the saved state. */
	private String activity;

	public UnlockPath()
	{
	}

	public UnlockPath(PathType type, List<Requirement> reqs, String source)
	{
		this.type = type;
		this.reqs = reqs;
		this.source = source;
	}

	public PathType getType()
	{
		return type == null ? PathType.SKILL : type;
	}

	public List<Requirement> getReqs()
	{
		return reqs == null ? Collections.emptyList() : reqs;
	}

	public String getSource()
	{
		return source;
	}

	public String getActivity()
	{
		return activity;
	}

	/** Human readable requirement line, e.g. "Crafting 80 + Magic 68". */
	public String describe()
	{
		return describeTrade();
	}

	/** Trade and shop requirements only. */
	public String describeTrade()
	{
		if (getType() == PathType.ACTIVITY)
		{
			return source != null ? source : String.valueOf(activity);
		}
		List<Requirement> tradeReqs = new ArrayList<>();
		for (Requirement req : getReqs())
		{
			if (req.isTradeOnly() || req.isActivateOnly())
			{
				tradeReqs.add(req);
			}
		}
		if (tradeReqs.isEmpty())
		{
			return "";
		}
		return tradeReqs.stream().map(Requirement::toString).collect(Collectors.joining(" + "));
	}
}

package com.leadman.rules;

/**
 * How an item is spent when it is used. This is the single predicate that decides
 * whether the USE gate applies to an item at all -- see docs/DESIGN.md section 2.
 *
 * TRADE is gated on every item regardless of this value.
 */
public enum ConsumeClass
{
	/** Eaten. Destroyed on use. */
	FOOD,
	/** Drunk. Consumes a dose. */
	POTION,
	/** Arrows, bolts, darts, javelins, chinchompas. Consumed when fired. */
	AMMO,
	/** Runes. Consumed when cast. */
	RUNE,
	/**
	 * Jewellery, plain or enchanted. Nothing in the game stops you putting on an amulet,
	 * so the Crafting level that made it is the requirement Leadman supplies. Split from
	 * {@link #CHARGED} because wearing one and firing its teleport are separate acts
	 * gated by separate skills: Crafting to wear, Magic to activate.
	 */
	JEWELLERY,
	/** Teleport tabs and scrolls, and the charge half of enchanted jewellery. */
	CHARGED,
	/** Permanent weapons, armour and shields. Wielding costs nothing. */
	EQUIPMENT,
	/**
	 * Basic elemental staves. Wielding supplies runes, so the RC level for that element
	 * gates wield when {@link com.leadman.LeadmanConfig#gateRunes()} is on.
	 */
	ELEMENTAL_STAFF,
	/** Axes, pickaxes, harpoons, knives, needles, hammers. */
	TOOL,
	/** Materials and everything else. Never USE-gated. */
	NONE
}

package com.leadman.rules;

/** How an item can legitimately enter a Leadman account. */
public enum ItemClass
{
	/** A skilling recipe produces it. */
	FABRICABLE,
	/** A gathering skill produces it directly (raw fish, logs, ores, herbs). */
	GATHERABLE,
	/** No recipe exists. Unlocks for trade on first obtain, Bronzeman style. */
	DROP_ONLY,
	/** Quest, diary, minigame or activity reward. */
	REWARD_ONLY,
	/** Only sold in NPC shops — buying counts as obtain; use allowed once held. */
	SHOP_ONLY,
	/** No level attached to it at all. Open on both gates by default. */
	FREE
}

package com.leadman.rules;

import net.runelite.api.Skill;

/**
 * One skill level requirement. Deserialised straight from the rules JSON, so the
 * skill is carried as a string and resolved lazily -- an unknown skill name must not
 * blow up the whole ruleset.
 */
public class Requirement
{
	private String skill;
	private int level;

	/**
	 * "ACTIVATE" marks a requirement that guards using an item's charge rather than
	 * holding or wearing it. An amulet of glory carries Crafting 80 unscoped and Magic 68
	 * scoped to ACTIVATE: 80 Crafting puts it round your neck, 68 Magic fires the
	 * teleport. Null means the requirement applies to everything.
	 */
	private String scope;

	private transient Skill resolved;
	private transient boolean resolveAttempted;

	public Requirement()
	{
	}

	public Requirement(Skill skill, int level)
	{
		this.skill = skill.name();
		this.level = level;
		this.resolved = skill;
		this.resolveAttempted = true;
	}

	public int getLevel()
	{
		return level;
	}

	public String getSkillName()
	{
		return skill;
	}

	/** True when this requirement guards the charge, not wearing or holding the item. */
	public boolean isActivateOnly()
	{
		return "ACTIVATE".equalsIgnoreCase(scope);
	}

	/** True when this requirement guards using a tool (e.g. Woodcutting to chop). */
	public boolean isUseOnly()
	{
		return "USE".equalsIgnoreCase(scope);
	}

	/** True when this requirement guards wielding equipment (e.g. Attack to wield). */
	public boolean isWieldOnly()
	{
		return "WIELD".equalsIgnoreCase(scope);
	}

	/** True when this requirement guards eating food. */
	public boolean isEatOnly()
	{
		return "EAT".equalsIgnoreCase(scope);
	}

	/** True when this requirement guards drinking a potion. */
	public boolean isDrinkOnly()
	{
		return "DRINK".equalsIgnoreCase(scope);
	}

	/** True when this requirement guards burying bones or ashes. */
	public boolean isBuryOnly()
	{
		return "BURY".equalsIgnoreCase(scope);
	}

	/** True when this requirement is part of the fabrication / trade recipe. */
	public boolean isTradeOnly()
	{
		return scope == null || scope.isEmpty()
			|| "TRADE".equalsIgnoreCase(scope);
	}

	/**
	 * @return the resolved skill, or null if the rules file names a skill this client
	 * does not know about (new skill, typo, or a renamed enum constant).
	 */
	public Skill getSkill()
	{
		if (!resolveAttempted)
		{
			resolveAttempted = true;
			try
			{
				resolved = Skill.valueOf(skill.toUpperCase());
			}
			catch (IllegalArgumentException | NullPointerException e)
			{
				resolved = null;
			}
		}
		return resolved;
	}

	@Override
	public String toString()
	{
		return prettySkill() + " " + level;
	}

	/** Skill enum constants are SCREAMING_CASE; players read "Runecrafting". */
	public String prettySkill()
	{
		Skill s = getSkill();
		String raw = s == null ? String.valueOf(skill) : s.name();
		if (raw.isEmpty())
		{
			return raw;
		}
		return raw.charAt(0) + raw.substring(1).toLowerCase();
	}
}

package com.leadman.rules;

import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;

/**
 * The gate definition for one canonical item.
 *
 * <p>Rules are keyed by <em>normalised name</em> rather than item id. Names are stable
 * across game updates and collapse charge/degrade/ornament variants for free, whereas
 * ids churn and would need a regenerated table every patch. See
 * {@link com.leadman.rules.ItemNames}.
 */
public class ItemRule
{
	/** Normalised lookup key, e.g. "amulet of glory". */
	private String name;
	/** Display name for the UI, e.g. "Amulet of glory". */
	private String display;
	private ItemClass itemClass;
	private ConsumeClass consume;
	private List<UnlockPath> paths;
	/** When set, shop buy is allowed only after {@code packOf} appears in {@code obtained}. */
	private String packOf;
	/** Ticket/pearl shops: no Leadman shop gate (the game already gates currency). */
	private boolean shopAlwaysOpen;

	public ItemRule()
	{
	}

	public ItemRule(String name, String display, ItemClass itemClass, ConsumeClass consume, List<UnlockPath> paths)
	{
		this.name = name;
		this.display = display;
		this.itemClass = itemClass;
		this.consume = consume;
		this.paths = paths;
	}

	public String getName()
	{
		return name;
	}

	public String getDisplay()
	{
		return display != null ? display : name;
	}

	public ItemClass getItemClass()
	{
		return itemClass == null ? ItemClass.FREE : itemClass;
	}

	public ConsumeClass getConsume()
	{
		return consume == null ? ConsumeClass.NONE : consume;
	}

	public List<UnlockPath> getPaths()
	{
		return paths == null ? Collections.emptyList() : paths;
	}

	/** Normalised key of the single item that must be obtained before this pack can be bought. */
	public String getPackOf()
	{
		return packOf;
	}

	public boolean isShopAlwaysOpen()
	{
		return shopAlwaysOpen;
	}

	public boolean hasSkillPath()
	{
		return getPaths().stream().anyMatch(p -> p.getType() == PathType.SKILL
			&& p.getReqs().stream().anyMatch(r -> r.isTradeOnly() || r.isActivateOnly()));
	}

	/** "Crafting 80 + Magic 68, or Smithing 90" -- trade/fabrication reqs only. */
	public String describeRequirements()
	{
		if (getPaths().isEmpty())
		{
			return "obtain one";
		}
		return getPaths().stream()
			.map(UnlockPath::describeTrade)
			.filter(s -> !s.isEmpty())
			.collect(Collectors.joining(", or "));
	}

	void setName(String name)
	{
		this.name = name;
	}
}

package com.leadman.unlock;

import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.Set;

/**
 * Everything about a Leadman profile that cannot be recomputed.
 *
 * <p>Deliberately absent: which items are currently fabricable. That is derived from
 * live skill levels on every login, so it can never drift out of sync with the account
 * and never needs migrating when the ruleset changes.
 */
public class UnlockState
{
	private int version = 1;

	/** Normalised names of every item this account has held at least once. */
	private Set<String> obtained = new LinkedHashSet<>();

	/** Completed quests, diaries and activities, by rule key. */
	private Set<String> activities = new HashSet<>();

	/** Unlocks already shown, so a popup never fires twice for the same item. */
	private Set<String> seen = new HashSet<>();

	/** Unlock order for the sidebar (newest first). Full history; panel also merges obtained. */
	private java.util.List<String> recentUnlocked = new java.util.ArrayList<>();

	/** True once the first full scan has run, so login does not fire a popup storm. */
	private boolean seeded;

	public Set<String> getObtained()
	{
		if (obtained == null)
		{
			obtained = new LinkedHashSet<>();
		}
		return obtained;
	}

	public Set<String> getActivities()
	{
		if (activities == null)
		{
			activities = new HashSet<>();
		}
		return activities;
	}

	public Set<String> getSeen()
	{
		if (seen == null)
		{
			seen = new HashSet<>();
		}
		return seen;
	}

	public boolean isSeeded()
	{
		return seeded;
	}

	public void setSeeded(boolean seeded)
	{
		this.seeded = seeded;
	}

	public java.util.List<String> getRecentUnlocked()
	{
		if (recentUnlocked == null)
		{
			recentUnlocked = new java.util.ArrayList<>();
		}
		return recentUnlocked;
	}

	public int getVersion()
	{
		return version;
	}
}

package com.leadman.unlock;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import com.leadman.CraftingRangedEquipmentMode;
import com.leadman.EquipmentSmithingMode;
import com.leadman.LeadmanConfig;
import com.leadman.rules.ConsumeClass;
import com.leadman.rules.ItemNames;
import com.leadman.rules.ItemRule;
import com.leadman.rules.PathType;
import com.leadman.rules.Requirement;
import com.leadman.rules.RuleRepository;
import com.leadman.rules.SpellRule;
import com.leadman.rules.TradeableIndex;
import com.leadman.rules.UnlockPath;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.RuneLite;
import net.runelite.client.game.ItemManager;

/**
 * The gate engine. Everything the plugin blocks or allows resolves through here.
 *
 * <p>Two independent gates, per docs/DESIGN.md section 1:
 * <pre>
 * tradeUnlocked = fabricable OR (everObtained AND unmapped non-equippable GE)
 *                 OR (unmapped equippable GE)
 * useUnlocked   = fabricable OR no skill path (per gate toggles)
 *                 OR (unmapped equippable GE) OR (everObtained AND unmapped non-equippable GE)
 * </pre>
 * {@code everObtained} bypasses trade for drop-only items and unmapped GE supplies. Looting
 * a smithable plate does not unlock the Grand Exchange; it never grants the right to use it.
 */
@Slf4j
@Singleton
public class UnlockService
{
	private static final Type CUSTOM_RULES = new TypeToken<List<CustomRule>>()
	{
	}.getType();

	private final Client client;
	private final ItemManager itemManager;
	private final RuleRepository rules;
	private final TradeableIndex tradeableIndex;
	private final LeadmanConfig config;
	private final Gson gson;

	private UnlockState state = new UnlockState();
	private File stateFile;
	private boolean dirty;

	private Map<String, CustomRule> customRules = Collections.emptyMap();

	/** Rule keys currently fabricable. Diffed on level-up to find new unlocks. */
	private Set<String> satisfied = new HashSet<>();

	@Inject
	public UnlockService(Client client, ItemManager itemManager, RuleRepository rules,
						 TradeableIndex tradeableIndex, LeadmanConfig config, Gson gson)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.rules = rules;
		this.tradeableIndex = tradeableIndex;
		this.config = config;
		this.gson = gson;
	}

	// --------------------------------------------------------------- lifecycle

	/** Loads the profile for the logged-in account. Safe to call repeatedly. */
	public void loadProfile(long accountHash)
	{
		File dir = new File(RuneLite.RUNELITE_DIR, "leadman");
		if (!dir.exists() && !dir.mkdirs())
		{
			log.warn("Leadman: could not create {}", dir);
		}

		stateFile = new File(dir, accountHash + ".json");
		state = new UnlockState();

		if (stateFile.exists())
		{
			try (Reader r = Files.newBufferedReader(stateFile.toPath(), StandardCharsets.UTF_8))
			{
				UnlockState loaded = gson.fromJson(r, UnlockState.class);
				if (loaded != null)
				{
					state = loaded;
				}
			}
			catch (IOException | JsonSyntaxException e)
			{
				log.warn("Leadman: could not read {}, starting a fresh profile", stateFile, e);
			}
		}

		reloadCustomRules();
		dirty = true;
	}

	public void save()
	{
		if (!dirty || stateFile == null)
		{
			return;
		}
		try (Writer w = Files.newBufferedWriter(stateFile.toPath(), StandardCharsets.UTF_8))
		{
			gson.toJson(state, w);
			dirty = false;
		}
		catch (IOException e)
		{
			log.warn("Leadman: could not save {}", stateFile, e);
		}
	}

	public boolean isLoaded()
	{
		return stateFile != null;
	}

	public UnlockState getState()
	{
		return state;
	}

	public void reloadCustomRules()
	{
		Map<String, CustomRule> parsed = new LinkedHashMap<>();
		try
		{
			List<CustomRule> list = gson.fromJson(config.customRules(), CUSTOM_RULES);
			if (list != null)
			{
				for (CustomRule rule : list)
				{
					if (rule != null && rule.getKey() != null && !rule.getKey().isEmpty())
					{
						parsed.put(rule.getKey(), rule);
					}
				}
			}
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Leadman: custom rules are not valid JSON, ignoring them", e);
		}
		customRules = parsed;
	}

	public List<CustomRule> getCustomRules()
	{
		return new ArrayList<>(customRules.values());
	}

	public CustomRule getCustomRule(String key)
	{
		return customRules.get(key);
	}

	public void upsertCustomRule(CustomRule rule)
	{
		if (!rule.hasAnyGate())
		{
			removeCustomRule(rule.getKey());
			return;
		}
		List<CustomRule> all = new ArrayList<>(customRules.values());
		all.removeIf(r -> r.getKey().equals(rule.getKey()));
		all.add(rule);
		setCustomRules(all);
	}

	public void removeCustomRule(String key)
	{
		List<CustomRule> all = new ArrayList<>(customRules.values());
		all.removeIf(r -> r.getKey().equals(key));
		setCustomRules(all);
	}

	public void setCustomRules(List<CustomRule> list)
	{
		config.setCustomRules(gson.toJson(list));
		reloadCustomRules();
	}

	public void clearAllCustomRules()
	{
		setCustomRules(Collections.emptyList());
	}

	/** Records an unlock for the sidebar list (obtain or fabrication), newest first. */
	public void recordRecentUnlock(String key)
	{
		if (key == null || key.isEmpty())
		{
			return;
		}
		List<String> recent = state.getRecentUnlocked();
		recent.remove(key);
		recent.add(0, key);
		dirty = true;
	}

	public List<String> getRecentUnlockedKeys()
	{
		return Collections.unmodifiableList(new ArrayList<>(state.getRecentUnlocked()));
	}

	/**
	 * Every item to show in the sidebar: recent unlock order first, then other obtained
	 * and fabrication unlocks alphabetically.
	 */
	public List<String> getPanelUnlockKeys()
	{
		Set<String> seen = new LinkedHashSet<>();
		List<String> keys = new ArrayList<>();

		for (String key : state.getRecentUnlocked())
		{
			if (seen.add(key))
			{
				keys.add(key);
			}
		}

		List<String> rest = new ArrayList<>();
		rest.addAll(state.getObtained());
		rest.addAll(satisfied);
		rest.removeAll(seen);
		Collections.sort(rest, String.CASE_INSENSITIVE_ORDER);
		keys.addAll(rest);
		return keys;
	}

	// ------------------------------------------------------------------ lookup

	/** Canonical rule key for an item id, unnoting and collapsing variants first. */
	public String keyFor(int itemId)
	{
		int canonical = itemManager.canonicalize(itemId);
		String geKey = tradeableIndex.geKeyForItemId(canonical);
		if (geKey != null && !geKey.isEmpty())
		{
			return geKey;
		}

		ItemComposition comp = itemManager.getItemComposition(canonical);
		return comp == null ? "" : ItemNames.normalise(comp.getName());
	}

	public String displayFor(int itemId)
	{
		int canonical = itemManager.canonicalize(itemId);
		ItemComposition comp = itemManager.getItemComposition(canonical);
		return comp == null ? "Item " + itemId : comp.getName();
	}

	// ------------------------------------------------------------------- gates

	public boolean canTrade(int itemId)
	{
		String key = keyFor(itemId);
		if (key.isEmpty())
		{
			return !tradeableIndex.isGeTradeableId(itemId);
		}
		return canTradeKey(key);
	}

	public boolean canTradeKey(String key)
	{
		if (key.isEmpty())
		{
			return true;
		}

		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateTrade())
		{
			// A custom rule is a deliberate hard lock. Obtaining the item does not
			// satisfy it, or "bones require 30 Prayer" would be defeated by one drop.
			return meets(custom.getTradeReqs());
		}

		ItemRule rule = rules.forName(key);
		if (rule != null && rule.hasSkillPath())
		{
			return canTradeFabricatedItem(key, rule);
		}

		if (rule != null && isObtainOnlyClass(rule.getItemClass()))
		{
			if (!tradeableIndex.isGeTradeableKey(key))
			{
				return true;
			}
			return state.getObtained().contains(key);
		}

		if (rule != null && rule.getItemClass() == com.leadman.rules.ItemClass.FREE)
		{
			if (!tradeableIndex.isGeTradeableKey(key))
			{
				return true;
			}
			return state.getObtained().contains(key);
		}

		if (rule != null && !rule.hasSkillPath())
		{
			if (tradeableIndex.isGeTradeableKey(key))
			{
				return false;
			}
			return satisfies(rule);
		}

		if (rule == null)
		{
			return unmappedGeAllowed(key);
		}
		return satisfies(rule);
	}

	public boolean canShopKey(String key)
	{
		if (key.isEmpty())
		{
			return true;
		}

		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateShop())
		{
			return meets(custom.getShopReqs());
		}

		if (custom != null && custom.isGateTrade())
		{
			return meets(custom.getTradeReqs());
		}

		ItemRule rule = rules.forName(key);
		if (rule != null && rule.getPackOf() != null && !rule.getPackOf().isEmpty())
		{
			return state.getObtained().contains(rule.getPackOf());
		}

		if (rule != null && rule.getItemClass() == com.leadman.rules.ItemClass.SHOP_ONLY)
		{
			return true;
		}

		if (rule != null && rule.isShopAlwaysOpen())
		{
			return true;
		}

		if (rule != null && rule.hasSkillPath())
		{
			return canTradeFabricatedItem(key, rule);
		}

		if (rule != null && isObtainOnlyClass(rule.getItemClass()))
		{
			if (!tradeableIndex.isGeTradeableKey(key))
			{
				return true;
			}
			return state.getObtained().contains(key);
		}

		if (rule != null && !rule.hasSkillPath())
		{
			if (tradeableIndex.isGeTradeableKey(key))
			{
				return state.getObtained().contains(key);
			}
			return true;
		}

		if (rule == null)
		{
			if (!tradeableIndex.isGeTradeableKey(key))
			{
				return true;
			}
			return unmappedGeAllowed(key);
		}
		return true;
	}

	public boolean canWield(int itemId)
	{
		return canWieldKey(keyFor(itemId));
	}

	public boolean canWieldKey(String key)
	{
		if (key.isEmpty())
		{
			return true;
		}

		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateWield())
		{
			return meets(custom.getWieldReqs());
		}

		ItemRule rule = rules.forName(key);
		if (rule == null)
		{
			return true;
		}

		List<Requirement> wieldReqs = wieldRequirements(rule);
		if (!wieldReqs.isEmpty() && wieldGateApplies(rule))
		{
			if (!meets(wieldReqs))
			{
				return false;
			}
		}

		ConsumeClass consume = rule.getConsume();
		if (!wearGateApplies(consume) || consume == ConsumeClass.FOOD || consume == ConsumeClass.POTION)
		{
			return true;
		}

		if (!rule.hasSkillPath())
		{
			return true;
		}

		return meetsEquipmentSmithingForWear(rule);
	}

	public boolean canEat(int itemId)
	{
		return canEatKey(keyFor(itemId));
	}

	public boolean canEatKey(String key)
	{
		if (key.isEmpty())
		{
			return true;
		}

		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateEat())
		{
			return meets(custom.getEatReqs());
		}

		ItemRule rule = rules.forName(key);
		if (rule == null || rule.getConsume() != ConsumeClass.FOOD)
		{
			return true;
		}

		if (!config.gateFood() || !rule.hasSkillPath())
		{
			return true;
		}

		return satisfies(rule, ReqFilter.WEAR);
	}

	public boolean canDrink(int itemId)
	{
		return canDrinkKey(keyFor(itemId));
	}

	public boolean canDrinkKey(String key)
	{
		if (key.isEmpty())
		{
			return true;
		}

		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateDrink())
		{
			return meets(custom.getDrinkReqs());
		}

		ItemRule rule = rules.forName(key);
		if (rule == null || rule.getConsume() != ConsumeClass.POTION)
		{
			return true;
		}

		if (!config.gatePotions() || !rule.hasSkillPath())
		{
			return true;
		}

		return satisfies(rule, ReqFilter.WEAR);
	}

	public boolean canBury(int itemId)
	{
		return canBuryKey(keyFor(itemId));
	}

	public boolean canBuryKey(String key)
	{
		if (key.isEmpty())
		{
			return true;
		}

		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateBury())
		{
			return meets(custom.getBuryReqs());
		}

		ItemRule rule = rules.forName(key);
		if (rule == null)
		{
			return true;
		}

		List<Requirement> buryReqs = buryRequirements(rule);
		return buryReqs.isEmpty() || meets(buryReqs);
	}

	public boolean canUse(int itemId)
	{
		return canUseKey(keyFor(itemId));
	}

	public boolean canUseKey(String key)
	{
		if (key.isEmpty())
		{
			return true;
		}

		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateUse())
		{
			return meets(custom.getUseReqs());
		}

		ItemRule rule = rules.forName(key);
		if (rule == null)
		{
			if (!tradeableIndex.isGeTradeableKey(key))
			{
				return true;
			}
			return unmappedGeAllowed(key);
		}

		ConsumeClass consume = rule.getConsume();
		if (consume == ConsumeClass.FOOD || consume == ConsumeClass.POTION)
		{
			List<Requirement> useReqs = useRequirements(rule);
			return useReqs.isEmpty() || meets(useReqs, ReqFilter.USE);
		}

		List<Requirement> useReqs = useRequirements(rule);
		if (!useReqs.isEmpty())
		{
			if (!meets(useReqs, ReqFilter.USE))
			{
				return false;
			}
			if (wearGateApplies(consume))
			{
				return meetsEquipmentSmithingForWear(rule);
			}
			return true;
		}

		if (!rule.hasSkillPath())
		{
			if (rule.getItemClass() == com.leadman.rules.ItemClass.SHOP_ONLY)
			{
				return state.getObtained().contains(key) || hasItemHeld(key);
			}
			if (tradeableIndex.isGeTradeableKey(key) && !state.getObtained().contains(key))
			{
				return false;
			}
			return true;
		}

		if (!wearGateApplies(consume))
		{
			return true;
		}

		return meetsEquipmentSmithingForWear(rule);
	}

	/**
	 * Whether an item's charge may be spent -- rubbing a glory, firing its teleport.
	 *
	 * <p>Separate from {@link #canUseKey} because wearing a piece of jewellery and using
	 * what it does are gated by different skills: Crafting made the amulet, Magic put the
	 * teleports in it. Turning off the Crafting gate must not also hand over the
	 * teleports, and turning off the Magic gate must not stop you wearing it.
	 */
	public boolean canActivate(int itemId)
	{
		return canActivateKey(keyFor(itemId));
	}

	public boolean canActivateKey(String key)
	{
		if (key.isEmpty())
		{
			return true;
		}

		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateActivate())
		{
			return meets(custom.getActivateReqs());
		}

		// You cannot spend a charge on something you are not allowed to hold or wear.
		if (!canUseKey(key))
		{
			return false;
		}

		ItemRule rule = rules.forName(key);
		if (rule == null || !rule.hasSkillPath())
		{
			return true;
		}

		if (!activateGateApplies(rule.getConsume()))
		{
			return true;
		}

		List<Requirement> activateReqs = collectRequirements(rule, ReqFilter.ACTIVATE);
		if (activateReqs.isEmpty())
		{
			// Plain jewellery (gold necklace, etc.) has no charge to spend.
			return true;
		}

		return meets(activateReqs);
	}

	private boolean hasActivateRequirements(ItemRule rule)
	{
		return !collectRequirements(rule, ReqFilter.ACTIVATE).isEmpty();
	}

	/** True when this item has a charge worth gating separately. */
	public boolean isActivatable(String key)
	{
		ItemRule rule = rules.forName(key);
		if (rule == null)
		{
			return false;
		}
		ConsumeClass consume = rule.getConsume();
		if (consume == ConsumeClass.CHARGED)
		{
			return true;
		}
		if (consume == ConsumeClass.JEWELLERY)
		{
			return hasActivateRequirements(rule);
		}
		return false;
	}

	/**
	 * @return true when a cast is permitted. Blocked when any rune the spell consumes
	 * is itself locked -- gating at the cast rather than the item, so an elemental
	 * staff cannot supply a rune the player could not craft.
	 */
	public boolean canCast(String spellName)
	{
		if (!runeGateOn())
		{
			return true;
		}

		SpellRule spell = rules.forSpell(spellName);
		if (spell == null)
		{
			// Unmapped spell. Allowing it is the safe failure: a false block is a bug
			// the player experiences, a false allow is a rule they can self-enforce.
			return true;
		}

		for (String rune : spell.getRunes())
		{
			ItemRule rule = rules.forName(rune);
			if (rule != null && !satisfies(rule))
			{
				return false;
			}
		}
		return true;
	}

	/** Runes are only use-gated when the player opts in; spells carry Magic levels already. */
	private boolean runeGateOn()
	{
		return config.gateRunes();
	}

	/** The first rune of this spell the player cannot craft, for the block message. */
	public String missingRuneFor(String spellName)
	{
		SpellRule spell = rules.forSpell(spellName);
		if (spell == null)
		{
			return null;
		}
		for (String rune : spell.getRunes())
		{
			ItemRule rule = rules.forName(rune);
			if (rule != null && !satisfies(rule))
			{
				return rule.getDisplay() + " (" + rule.describeRequirements() + ")";
			}
		}
		return null;
	}

	// ------------------------------------------------------------ gate policy

	/** WIELD-scoped reqs on equipment always apply; elemental staves only when runes are gated. */
	private boolean wieldGateApplies(ItemRule rule)
	{
		if (wieldRequirements(rule).isEmpty())
		{
			return false;
		}
		if (rule.getConsume() == ConsumeClass.ELEMENTAL_STAFF)
		{
			return runeGateOn();
		}
		return true;
	}

	/** Applies to eat, drink, wear and wield. */
	private boolean wearGateApplies(ConsumeClass consume)
	{
		if (consume == ConsumeClass.NONE)
		{
			return false;
		}

		switch (consume)
		{
			case FOOD:
				return config.gateFood();
			case POTION:
				return config.gatePotions();
			case AMMO:
				return config.gateAmmo();
			case RUNE:
				return config.gateRunes();
			case JEWELLERY:
				return config.gateJewel();
			case CHARGED:
				return config.gateCharged();
			case EQUIPMENT:
				return true;
			case ELEMENTAL_STAFF:
				return runeGateOn();
			default:
				return false;
		}
	}

	/** Applies to rubbing, teleporting and anything else that spends a charge. */
	private boolean activateGateApplies(ConsumeClass consume)
	{
		if (consume == ConsumeClass.JEWELLERY || consume == ConsumeClass.CHARGED)
		{
			return config.gateCharged();
		}
		return wearGateApplies(consume);
	}

	private boolean meetsFabricationForTrade(ItemRule rule)
	{
		if (isSmithingEquipment(rule))
		{
			return meetsEquipmentSmithingForTrade(rule);
		}
		if (isFabricatedRangedEquipment(rule))
		{
			return meetsFabricatedRangedForTrade(rule);
		}
		return satisfies(rule);
	}

	/** Skill-path items need a legitimate obtain before GE/shop; then fabrication levels apply. */
	private boolean canTradeFabricatedItem(String key, ItemRule rule)
	{
		if (!state.getObtained().contains(key))
		{
			return false;
		}
		return meetsFabricationForTrade(rule);
	}

	private boolean isSmithingEquipment(ItemRule rule)
	{
		return rule.getConsume() == ConsumeClass.EQUIPMENT && smithingTradeLevel(rule) > 0;
	}

	/**
	 * Leather, dragonhide, snakeskin, and Fletching-made bows/crossbows. Excludes
	 * battlestaves (Crafting + Magic) and smithing gear.
	 */
	private boolean isFabricatedRangedEquipment(ItemRule rule)
	{
		if (rule.getConsume() != ConsumeClass.EQUIPMENT || isSmithingEquipment(rule))
		{
			return false;
		}

		int crafting = craftingTradeLevel(rule);
		if (crafting > 0 && !hasMagicTradeRequirement(rule))
		{
			return true;
		}

		return fletchingTradeLevel(rule) > 0;
	}

	private boolean hasMagicTradeRequirement(ItemRule rule)
	{
		for (Requirement req : tradeRequirements(rule))
		{
			if (req.getSkill() == Skill.MAGIC)
			{
				return true;
			}
		}
		return false;
	}

	private int craftingTradeLevel(ItemRule rule)
	{
		for (Requirement req : tradeRequirements(rule))
		{
			if (req.getSkill() == Skill.CRAFTING)
			{
				return req.getLevel();
			}
		}
		return 0;
	}

	private int fletchingTradeLevel(ItemRule rule)
	{
		for (Requirement req : tradeRequirements(rule))
		{
			if (req.getSkill() == Skill.FLETCHING)
			{
				return req.getLevel();
			}
		}
		return 0;
	}

	private boolean meetsFabricatedRangedForWear(ItemRule rule)
	{
		switch (config.craftingRangedEquipmentMode())
		{
			case RESTRICT:
				return satisfies(rule, ReqFilter.WEAR);
			case BALANCED:
			case MIXED:
				return meetsBalancedFabricatedRanged(rule);
			default:
				return satisfies(rule, ReqFilter.WEAR);
		}
	}

	private boolean meetsFabricatedRangedForTrade(ItemRule rule)
	{
		switch (config.craftingRangedEquipmentMode())
		{
			case BALANCED:
				return meetsBalancedFabricatedRanged(rule);
			case RESTRICT:
			case MIXED:
				return satisfies(rule);
			default:
				return satisfies(rule);
		}
	}

	private boolean meetsBalancedFabricatedRanged(ItemRule rule)
	{
		int crafting = craftingTradeLevel(rule);
		if (crafting > 0 && !hasMagicTradeRequirement(rule))
		{
			int level = balancedCraftingRangedLevel(rule);
			if (level <= 0)
			{
				return satisfies(rule, ReqFilter.WEAR);
			}
			return client.getRealSkillLevel(Skill.CRAFTING) >= level;
		}

		int fletching = fletchingTradeLevel(rule);
		if (fletching > 0)
		{
			int level = balancedFletchingRangedLevel(rule);
			if (level <= 0)
			{
				return satisfies(rule, ReqFilter.WEAR);
			}
			return client.getRealSkillLevel(Skill.FLETCHING) >= level;
		}

		return true;
	}

	/** Crafting level tied to vanilla Ranged/Defence wield reqs; falls back to fabrication. */
	private int balancedCraftingRangedLevel(ItemRule rule)
	{
		int max = 0;
		for (Requirement req : wieldRequirements(rule))
		{
			Skill skill = req.getSkill();
			if (skill == Skill.RANGED || skill == Skill.DEFENCE)
			{
				max = Math.max(max, req.getLevel());
			}
		}
		if (max > 0)
		{
			return max;
		}
		return craftingTradeLevel(rule);
	}

	/** Fletching level tied to vanilla Ranged wield reqs; falls back to fabrication. */
	private int balancedFletchingRangedLevel(ItemRule rule)
	{
		int max = 0;
		for (Requirement req : wieldRequirements(rule))
		{
			if (req.getSkill() == Skill.RANGED)
			{
				max = Math.max(max, req.getLevel());
			}
		}
		if (max > 0)
		{
			return max;
		}
		return fletchingTradeLevel(rule);
	}

	private List<Requirement> fabricatedRangedDisplayRequirements(ItemRule rule)
	{
		if (!isFabricatedRangedEquipment(rule))
		{
			return Collections.emptyList();
		}

		int level;
		Skill skill;
		switch (config.craftingRangedEquipmentMode())
		{
			case RESTRICT:
				if (craftingTradeLevel(rule) > 0 && !hasMagicTradeRequirement(rule))
				{
					return Collections.singletonList(
						new Requirement(Skill.CRAFTING, craftingTradeLevel(rule)));
				}
				if (fletchingTradeLevel(rule) > 0)
				{
					return Collections.singletonList(
						new Requirement(Skill.FLETCHING, fletchingTradeLevel(rule)));
				}
				return Collections.emptyList();
			case BALANCED:
			case MIXED:
				if (craftingTradeLevel(rule) > 0 && !hasMagicTradeRequirement(rule))
				{
					skill = Skill.CRAFTING;
					level = balancedCraftingRangedLevel(rule);
				}
				else if (fletchingTradeLevel(rule) > 0)
				{
					skill = Skill.FLETCHING;
					level = balancedFletchingRangedLevel(rule);
				}
				else
				{
					return Collections.emptyList();
				}
				break;
			default:
				return Collections.emptyList();
		}

		return level > 0
			? Collections.singletonList(new Requirement(skill, level))
			: Collections.emptyList();
	}

	private List<Requirement> fabricatedRangedTradeDisplayRequirements(ItemRule rule)
	{
		if (!isFabricatedRangedEquipment(rule))
		{
			return Collections.emptyList();
		}

		if (config.craftingRangedEquipmentMode() == CraftingRangedEquipmentMode.BALANCED)
		{
			return fabricatedRangedDisplayRequirements(rule);
		}

		if (craftingTradeLevel(rule) > 0 && !hasMagicTradeRequirement(rule))
		{
			return Collections.singletonList(new Requirement(Skill.CRAFTING, craftingTradeLevel(rule)));
		}
		if (fletchingTradeLevel(rule) > 0)
		{
			return Collections.singletonList(new Requirement(Skill.FLETCHING, fletchingTradeLevel(rule)));
		}
		return Collections.emptyList();
	}

	private int smithingTradeLevel(ItemRule rule)
	{
		for (Requirement req : tradeRequirements(rule))
		{
			if (req.getSkill() == Skill.SMITHING)
			{
				return req.getLevel();
			}
		}
		return 0;
	}

	/** Smithing level tied to vanilla Attack/Defence/Ranged wield reqs; falls back to fabrication. */
	private int balancedSmithingLevel(ItemRule rule)
	{
		int max = 0;
		for (Requirement req : wieldRequirements(rule))
		{
			max = Math.max(max, req.getLevel());
		}
		if (max > 0)
		{
			return max;
		}
		return smithingTradeLevel(rule);
	}

	private boolean meetsBalancedSmithing(ItemRule rule)
	{
		int level = balancedSmithingLevel(rule);
		if (level <= 0)
		{
			return satisfies(rule, ReqFilter.WEAR);
		}
		return client.getRealSkillLevel(Skill.SMITHING) >= level;
	}

	private boolean meetsEquipmentSmithingForWear(ItemRule rule)
	{
		if (isSmithingEquipment(rule))
		{
			switch (config.equipmentSmithingMode())
			{
				case RESTRICT:
					return satisfies(rule, ReqFilter.WEAR);
				case BALANCED:
				case MIXED:
					return meetsBalancedSmithing(rule);
				default:
					return satisfies(rule, ReqFilter.WEAR);
			}
		}

		if (isFabricatedRangedEquipment(rule))
		{
			return meetsFabricatedRangedForWear(rule);
		}

		return satisfies(rule, ReqFilter.WEAR);
	}

	private boolean meetsEquipmentSmithingForTrade(ItemRule rule)
	{
		if (!isSmithingEquipment(rule))
		{
			return satisfies(rule);
		}

		switch (config.equipmentSmithingMode())
		{
			case BALANCED:
				return meetsBalancedSmithing(rule);
			case RESTRICT:
			case MIXED:
				return satisfies(rule);
			default:
				return satisfies(rule);
		}
	}

	private List<Requirement> equipmentSmithingDisplayRequirements(ItemRule rule)
	{
		if (!isSmithingEquipment(rule))
		{
			return Collections.emptyList();
		}

		int level;
		switch (config.equipmentSmithingMode())
		{
			case RESTRICT:
				level = smithingTradeLevel(rule);
				break;
			case BALANCED:
			case MIXED:
				level = balancedSmithingLevel(rule);
				break;
			default:
				return Collections.emptyList();
		}

		return level > 0
			? Collections.singletonList(new Requirement(Skill.SMITHING, level))
			: Collections.emptyList();
	}

	private List<Requirement> equipmentSmithingTradeDisplayRequirements(ItemRule rule)
	{
		if (!isSmithingEquipment(rule))
		{
			return Collections.emptyList();
		}

		if (config.equipmentSmithingMode() == EquipmentSmithingMode.BALANCED)
		{
			return equipmentSmithingDisplayRequirements(rule);
		}

		int level = smithingTradeLevel(rule);
		return level > 0
			? Collections.singletonList(new Requirement(Skill.SMITHING, level))
			: Collections.emptyList();
	}

	/**
	 * Which half of an item's requirements a check cares about.
	 *
	 * <p>An amulet of glory carries Crafting 80 and Magic 68. Trading one needs both --
	 * you have to be able to make the whole thing. Wearing it needs the Crafting half.
	 * Firing its teleport needs the Magic half, and only that half: with the Crafting
	 * gate switched off, a glory you were allowed to put on must not then demand
	 * 80 Crafting before it will teleport you.
	 */
	private enum ReqFilter
	{
		/** Trade and shop: every requirement except USE and WIELD. */
		TRADE,
		/** Eat, drink, wear jewellery: fabrication reqs without ACTIVATE/USE/WIELD. */
		WEAR,
		/** Tool use: USE-scoped reqs only. */
		USE,
		/** Wield weapons and armour: WIELD-scoped reqs only. */
		WIELD,
		/** Charge spend: ACTIVATE-scoped reqs only. */
		ACTIVATE,
		/** Bury bones or ashes. */
		BURY
	}

	/** Trade needs every fabrication requirement: you must be able to make the whole item. */
	private boolean satisfies(ItemRule rule)
	{
		return satisfies(rule, ReqFilter.TRADE);
	}

	private List<Requirement> tradeRequirements(ItemRule rule)
	{
		return collectRequirements(rule, ReqFilter.TRADE);
	}

	private List<Requirement> useRequirements(ItemRule rule)
	{
		return collectRequirements(rule, ReqFilter.USE);
	}

	private List<Requirement> wieldRequirements(ItemRule rule)
	{
		return collectRequirements(rule, ReqFilter.WIELD);
	}

	private List<Requirement> buryRequirements(ItemRule rule)
	{
		return collectRequirements(rule, ReqFilter.BURY);
	}

	private List<Requirement> eatRequirements(ItemRule rule)
	{
		if (rule.getConsume() != ConsumeClass.FOOD)
		{
			return Collections.emptyList();
		}
		return tradeRequirements(rule);
	}

	private List<Requirement> drinkRequirements(ItemRule rule)
	{
		if (rule.getConsume() != ConsumeClass.POTION)
		{
			return Collections.emptyList();
		}
		return tradeRequirements(rule);
	}

	private List<Requirement> collectRequirements(ItemRule rule, ReqFilter filter)
	{
		List<Requirement> collected = new ArrayList<>();
		for (UnlockPath path : rule.getPaths())
		{
			if (path.getType() != PathType.SKILL)
			{
				continue;
			}
			for (Requirement req : path.getReqs())
			{
				if (matchesFilter(req, filter))
				{
					collected.add(req);
				}
			}
			if (!collected.isEmpty())
			{
				return collected;
			}
		}
		return collected;
	}

	private static boolean isObtainOnlyClass(com.leadman.rules.ItemClass itemClass)
	{
		return itemClass == com.leadman.rules.ItemClass.DROP_ONLY
			|| itemClass == com.leadman.rules.ItemClass.REWARD_ONLY
			|| itemClass == com.leadman.rules.ItemClass.SHOP_ONLY;
	}

	/**
	 * Unmapped GE items with no fabrication rule: equippable gear trades freely; everything
	 * else needs one genuine obtain before trade, shop or use opens up.
	 */
	private boolean unmappedGeAllowed(String key)
	{
		if (!tradeableIndex.isGeTradeableKey(key))
		{
			return true;
		}
		return state.getObtained().contains(key);
	}

	private static boolean matchesFilter(Requirement req, ReqFilter filter)
	{
		switch (filter)
		{
			case TRADE:
				return req.isTradeOnly() || req.isActivateOnly();
			case WEAR:
				return req.isTradeOnly();
			case USE:
				return req.isUseOnly();
			case WIELD:
				return req.isWieldOnly();
			case ACTIVATE:
				return req.isActivateOnly();
			case BURY:
				return req.isBuryOnly();
			default:
				return false;
		}
	}

	private boolean satisfies(ItemRule rule, ReqFilter filter)
	{
		List<UnlockPath> paths = rule.getPaths();
		if (paths.isEmpty())
		{
			// No mapped path: drop-only or free. Trade handles this via everObtained;
			// use is never gated on it.
			return rule.getItemClass() == com.leadman.rules.ItemClass.FREE;
		}

		for (UnlockPath path : paths)
		{
			if (path.getType() == PathType.ACTIVITY)
			{
				if (path.getActivity() != null && state.getActivities().contains(path.getActivity()))
				{
					return true;
				}
				continue;
			}
			if (meets(path.getReqs(), filter))
			{
				return true;
			}
		}
		return false;
	}

	private boolean meets(List<Requirement> reqs)
	{
		if (reqs.isEmpty())
		{
			return true;
		}
		for (Requirement req : reqs)
		{
			Skill skill = req.getSkill();
			if (skill == null)
			{
				return false;
			}
			if (client.getRealSkillLevel(skill) < req.getLevel())
			{
				return false;
			}
		}
		return true;
	}

	private boolean meets(List<Requirement> reqs, ReqFilter filter)
	{
		boolean matched = false;
		for (Requirement req : reqs)
		{
			if (!matchesFilter(req, filter))
			{
				continue;
			}
			matched = true;
			Skill skill = req.getSkill();
			if (skill == null)
			{
				return false;
			}
			if (client.getRealSkillLevel(skill) < req.getLevel())
			{
				return false;
			}
		}
		return matched;
	}

	public List<Requirement> displayTradeRequirements(String key)
	{
		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateTrade())
		{
			return custom.getTradeReqs();
		}
		ItemRule rule = rules.forName(key);
		if (rule == null)
		{
			return Collections.emptyList();
		}

		List<Requirement> smithing = equipmentSmithingTradeDisplayRequirements(rule);
		if (!smithing.isEmpty())
		{
			return smithing;
		}
		List<Requirement> ranged = fabricatedRangedTradeDisplayRequirements(rule);
		if (!ranged.isEmpty())
		{
			return ranged;
		}
		return tradeRequirements(rule);
	}

	public List<Requirement> displayShopRequirements(String key)
	{
		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateShop())
		{
			return custom.getShopReqs();
		}
		if (custom != null && custom.isGateTrade())
		{
			return custom.getTradeReqs();
		}
		return displayTradeRequirements(key);
	}

	public List<Requirement> displayEatRequirements(String key)
	{
		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateEat())
		{
			return custom.getEatReqs();
		}
		ItemRule rule = rules.forName(key);
		return rule == null || !config.gateFood() ? Collections.emptyList() : eatRequirements(rule);
	}

	public List<Requirement> displayDrinkRequirements(String key)
	{
		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateDrink())
		{
			return custom.getDrinkReqs();
		}
		ItemRule rule = rules.forName(key);
		return rule == null || !config.gatePotions() ? Collections.emptyList() : drinkRequirements(rule);
	}

	public List<Requirement> displayActivateRequirements(String key)
	{
		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateActivate())
		{
			return custom.getActivateReqs();
		}
		ItemRule rule = rules.forName(key);
		if (rule == null || !activateGateApplies(rule.getConsume()))
		{
			return Collections.emptyList();
		}
		return collectRequirements(rule, ReqFilter.ACTIVATE);
	}

	public List<Requirement> displayBuryRequirements(String key)
	{
		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateBury())
		{
			return custom.getBuryReqs();
		}
		ItemRule rule = rules.forName(key);
		return rule == null ? Collections.emptyList() : buryRequirements(rule);
	}

	public List<Requirement> displayUseRequirements(String key)
	{
		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateUse())
		{
			return custom.getUseReqs();
		}
		ItemRule rule = rules.forName(key);
		return rule == null ? Collections.emptyList() : useRequirements(rule);
	}

	public List<Requirement> displayWieldRequirements(String key)
	{
		CustomRule custom = customRules.get(key);
		if (custom != null && custom.isGateWield())
		{
			return custom.getWieldReqs();
		}
		ItemRule rule = rules.forName(key);
		if (rule == null)
		{
			return Collections.emptyList();
		}

		List<Requirement> reqs = new ArrayList<>(wieldRequirements(rule));
		reqs.addAll(equipmentSmithingDisplayRequirements(rule));
		reqs.addAll(fabricatedRangedDisplayRequirements(rule));
		return reqs;
	}

	public boolean meetsTradeRequirements(String key)
	{
		return canTradeKey(key);
	}

	public boolean meetsShopRequirements(String key)
	{
		return canShopKey(key);
	}

	public boolean meetsUseRequirements(String key)
	{
		return canUseKey(key);
	}

	public boolean meetsEatRequirements(String key)
	{
		return canEatKey(key);
	}

	public boolean meetsDrinkRequirements(String key)
	{
		return canDrinkKey(key);
	}

	public boolean meetsWieldRequirements(String key)
	{
		return canWieldKey(key);
	}

	public boolean meetsActivateRequirements(String key)
	{
		return canActivateKey(key);
	}

	public boolean meetsBuryRequirements(String key)
	{
		return canBuryKey(key);
	}

	/** Why a charge cannot be spent -- the enchant level, not the whole recipe. */
	public String activateReason(String key)
	{
		ItemRule rule = rules.forName(key);
		if (rule == null)
		{
			return "unknown";
		}

		List<String> parts = new ArrayList<>();
		for (UnlockPath path : rule.getPaths())
		{
			for (Requirement req : path.getReqs())
			{
				if (req.isActivateOnly())
				{
					parts.add(req.toString());
				}
			}
		}
		return parts.isEmpty() ? rule.describeRequirements() : String.join(" + ", parts);
	}

	/** Why an item cannot be wielded, phrased for the chatbox. */
	public String wieldReason(String key)
	{
		List<Requirement> reqs = displayWieldRequirements(key);
		if (!reqs.isEmpty())
		{
			return reqs.stream().map(Requirement::toString).collect(java.util.stream.Collectors.joining(" + "));
		}
		return lockReason(key);
	}

	/** Why an item is locked, phrased for the chatbox. */
	public String lockReason(String key)
	{
		CustomRule custom = customRules.get(key);
		if (custom != null)
		{
			return custom.describe();
		}
		ItemRule rule = rules.forName(key);
		return rule == null ? "unknown" : rule.describeRequirements();
	}

	/** Shop block message -- uses shop override reqs when present. */
	public String shopReason(String key)
	{
		ItemRule rule = rules.forName(key);
		if (rule != null && rule.getPackOf() != null && !rule.getPackOf().isEmpty())
		{
			ItemRule component = rules.forName(rule.getPackOf());
			String name = component != null ? component.getDisplay() : rule.getPackOf();
			return "obtain " + name + " first";
		}

		List<Requirement> reqs = displayShopRequirements(key);
		if (!reqs.isEmpty())
		{
			return reqs.stream().map(Requirement::toString).collect(java.util.stream.Collectors.joining(" + "));
		}
		return lockReason(key);
	}

	// ------------------------------------------------------------- unlocking

	/**
	 * Records that the account has held this item. Only call this for items the player
	 * genuinely acquired -- shop purchases must not reach here, or shop stock would
	 * launder items onto the Grand Exchange.
	 *
	 * @return true if this was the first time
	 */
	public boolean markObtained(int itemId)
	{
		String key = keyFor(itemId);
		if (key.isEmpty())
		{
			return false;
		}
		if (state.getObtained().add(key))
		{
			recordRecentUnlock(key);
			dirty = true;
			return true;
		}
		return false;
	}

	public boolean hasObtained(String key)
	{
		return state.getObtained().contains(key);
	}

	public void markActivity(String activity)
	{
		if (state.getActivities().add(activity))
		{
			dirty = true;
		}
	}

	/** True when the item is anywhere in inventory, equipment or bank. */
	private boolean hasItemHeld(String key)
	{
		if (client.getGameState() != GameState.LOGGED_IN || key.isEmpty())
		{
			return false;
		}

		int[] containers = {
			InventoryID.INV,
			InventoryID.WORN,
			InventoryID.BANK,
		};
		for (int containerId : containers)
		{
			ItemContainer container = client.getItemContainer(containerId);
			if (container == null)
			{
				continue;
			}
			for (Item item : container.getItems())
			{
				if (item.getId() > 0 && key.equals(keyFor(item.getId())))
				{
					return true;
				}
			}
		}
		return false;
	}

	public boolean markSeen(String key)
	{
		if (state.getSeen().add(key))
		{
			dirty = true;
			return true;
		}
		return false;
	}

	/**
	 * Recomputes which rules are fabricable and returns the ones that just became so.
	 *
	 * @param silent true on the first scan of a profile, which records the baseline
	 *               without reporting it as a wave of unlocks
	 */
	public List<ItemRule> refreshSatisfied(boolean silent)
	{
		Set<String> now = new HashSet<>();
		List<ItemRule> newly = new ArrayList<>();

		for (Map.Entry<String, ItemRule> entry : rules.all().entrySet())
		{
			ItemRule rule = entry.getValue();
			if (!rule.hasSkillPath())
			{
				continue;
			}
			if (!satisfies(rule))
			{
				continue;
			}
			now.add(entry.getKey());
			if (!silent && !satisfied.contains(entry.getKey()))
			{
				newly.add(rule);
			}
		}

		satisfied = now;

		if (silent)
		{
			state.setSeeded(true);
			dirty = true;
			return Collections.emptyList();
		}
		return newly;
	}

	public boolean isSatisfiedKey(String key)
	{
		return satisfied.contains(key);
	}

	public RuleRepository getRules()
	{
		return rules;
	}
}

